code.init:
fac = 2; fac2 = .5; base = .55;
n = 20; rot = (2*$PI)/(n*.5); r1 = -rot*.5; r2 = -rot*.5;
in = 0; loop(n*.5,assign(gmegabuf(in),base)+assign(gmegabuf(in+1150),base)+assign(gmegabuf(in+1100),0)+assign(gmegabuf(in+1050),0)+assign(in,in+2));
in = 100; loop(n,assign(gmegabuf(in),.5)+assign(in,in+1));

code.perFrame:
 // load global aspect ratio correction and speed
asp1 = reg10;
asp2 = reg11;
speed = reg00;

 // move the couple around the screen [oxm & oym]
mr1 = mr1-(mr1-getosc(.3,0,0)*1.5)*pow(speed,1-b*.3);
mr2 = mr2-(mr2-getosc(.5,0,0)*1.5)*pow(speed,1-b*.3);
m1 = m1+mr1*speed*10;
m2 = m2+mr2*speed*10;
oxm = sin(m1)*.3-sin(m2)*.2;
oym = cos(m1)*.3-cos(m2)*.2;

 // rotate each of the circles [in fact, set the start value for "r" in the rendering of the circles]
rm1 = rm1-(rm1-getosc(0,0,0))*pow(speed,1);
r1 = r1+rm1*speed*20; reg25 = r1;
rm2 = rm2-(rm2-getosc(1,0,0))*pow(speed,1);
r2 = r2+rm2*speed*20; reg26 = r2;

 // move each circles to opposite sides of the center
 // movement [oxm&oym] and rotate around the couple's center
mr = mr-(mr-getosc(.7,0,0)*1.5)*pow(speed,1-b*.3);
m = m+mr*speed*5;
dm1 = dm1-(dm1-getosc(.7,0,0))*pow(speed,.5);
dm = dm+dm1*speed*15;
d = .6+sin(dm)*.1;
xm1 = oxm+sin(m)*d;  reg21 = xm1;
ym1 = oym+cos(m)*d;reg22 = ym1;
xm2 = oxm-sin(m)*d;  reg23 = xm2;
ym2 = oym-cos(m)*d; reg24 = ym2;

 // set speed values and factors for the bar movements
speed2 = pow(speed,.4);
speed3 = pow(speed,.8);
spec = spec-(spec-getspec(.3,.8,0))*speed;
speed4 = speed*(10+spec*30);

 // cosine-based target approach for blue 'circle', part 1 [move the bars]:
in = 0;
loop(n*.5,
 assign(gmegabuf(in),cos(gmegabuf(in+1050))*gmegabuf(in+1100)+gmegabuf(in+1150))+
 assign(gmegabuf(in+1100),gmegabuf(in+1100)-gmegabuf(in+1100)*speed3)+
 assign(gmegabuf(in+1050),gmegabuf(in+1050)+speed4)+
 assign(in,in+2));
 // part 2 [find new target if old target reached and [re]set offsets]:
in = 0;
loop(n*.5,
 if(below(abs(gmegabuf(in+1100)),.01),
  assign(gmegabuf(in+1150),base+getosc(in*.05+.05,0,0)*fac2)+
  assign(gmegabuf(in+1100),gmegabuf(in)-gmegabuf(in+1150))+
  assign(gmegabuf(in+1050),0),
  bleh)+
assign(in,in+2));

/* old blue movement
in = 0;
loop(n*.5,assign(gmegabuf(in),gmegabuf(in)-(gmegabuf(in)
-.5+getosc((in)*.05+.05,0,0)*fac2)*speed3)+
assign(gmegabuf(in+1),gmegabuf(in))+
assign(in,in+2));
*/

 // little orange 'circle' vertices 1&2 [3rd is always centered, see triangle box]
in = 100;
loop(n*.5,assign(gmegabuf(in),gmegabuf(in)-(gmegabuf(in)-
     .5+getosc((in-100)*.05,.1,0)*fac)*speed2)+assign(in,in+2));
in = 101;
loop(n*.5,assign(gmegabuf(in),gmegabuf(in)-(gmegabuf(in)-
     .5+getosc(1-(in-101)*.05,.1,0)*fac)*speed2)+assign(in,in+2));

 // fadeout beat variable and reset counter
b = b-b*pow(speed,.5);
c = -2;

code.perPoint:
 // if counter above half of the triangles [started with -2 and takes 2 steps each triangle]
 // render the 2nd circle [the small orange one, else the blue one]
state2 = above(c,17);
 // get specific circle origin
xm = if(state2,xm2,xm1);
ym = if(state2,ym2,ym1);
 // get specific rendering rotation position
r = if(state2,r2,r1);
 // increase counter
c = c+2;
 // get bar distance/movement from megabuf by counter values
d1 = gmegabuf(c+state2*80)*(1.5-.95*state2);
d2 = gmegabuf(c+state2*81)*(1.5-.95*state2);
 // set vertex one
x1 = sin(r-.04)*d1*asp1+xm;
y1 = cos(r-.04)*d1*asp2+ym;
 // move rotation position further
r1 = r1+rot*bnot(state2);
r2 = r2+rot*state2;
 // get specific rendering rotation position again since r1&r2 have just changed
r = if(state2,r2,r1);
 // set 2nd vertex
x2 = sin(r)*d2*asp1+xm;
y2 = cos(r)*d2*asp2+ym;
 // set 3rd vertex [always centered at the specific circle origin]
x3 = xm;
y3 = ym;

 // errr, well... uhm, colors maybe?
red1 = 1-state2;
blue1 = .2+state2*.75;
green1 = .4+state2*.3;

